ref_dict.cov-th:
\begin{theorem}[Limiting covariance]
\label{cov-th}
If Assumption B holds, then
for any $t,s>0$,
\[
\lim_{R \to \infty}\frac{1}{R^{\beta}}\bE[F_R(t) F_R(s)]=K(t,s) \quad \mbox{is finite},
\] 
where 
\begin{equation}
\label{def-beta}
\beta:=\left\{
\begin{array}{ll} 1 & \mbox{if $\k \in L^1(\bR)$,} \\
\alpha+1 & \mbox{if $\k=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$. }
\end{array} \right.
\end{equation}
In particular, $R^{-\beta} \sigma_R^2(t) \to K(t,t)$ as $R \to \infty$, for any $t>0$.
\end{theorem}

ref_dict.ergodic-th:
\begin{theorem}
\label{ergodic-th}
If Assumption B holds, then $\{u(t,x)\}_{x\in \bR}$ is ergodic, for any $t>0$. Consequently, by the mean ergodic theorem,
\[
\frac{1}{R}F_R(t) \to 0 \quad \mbox{a.s and in $L^2(\Omega)$}, \quad \mbox{as $R \to \infty$}.
\]
\end{theorem}

post_theorem_intro_text:
\begin{theorem}[Limiting covariance]
\label{cov-th}
If Assumption B holds, then
for any $t,s>0$,
\[
\lim_{R \to \infty}\frac{1}{R^{\beta}}\mathbb{E}[F_R(t) F_R(s)]=K(t,s) \quad \mbox{is finite},
\] 
where 
\begin{equation}
\label{def-beta}
\beta:=\left\{
\begin{array}{ll} 1 & \mbox{if $\kappa \in L^1(\mathbb{R})$,} \\
\alpha+1 & \mbox{if $\kappa=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$. }
\end{array} \right.
\end{equation}
In particular, $R^{-\beta} \sigma_R^2(t) \to K(t,t)$ as $R \to \infty$, for any $t>0$.
\end{theorem}

\begin{theorem}[Quantitative Central Limit Theorem]
\label{QCLT}
Suppose that Assumption B holds, and there exists $p \in (1,2]$ such that 
\begin{equation}
\label{mp-m2p}
m_{p}<\infty \quad \mbox{and} \quad m_{2p}<\infty.
\end{equation}

If $\kappa \in L^1(\mathbb{R})$, then
for any $t>0$,
\[
{\rm dist}\left( \frac{F_R(t)}{\sigma_R(t)},Z\right) \leq  C_t R^{-(1-\frac{1}{p})}
\]

If $\kappa=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$, and $p>\frac{2}{2-\alpha}$, then
\[
{\rm dist}\left( \frac{F_R(t)}{\sigma_R(t)},Z\right) \leq
C_t R^{-\varepsilon}  \quad \mbox{for any $\varepsilon \in \big(0, 1-\frac{1}{p}-\frac{\alpha}{2}\big)$}.
\]

Here $C_t>0$ is a constant depending on $t$, and ${\rm dist}$ is the Fortet-Mourier distance, the 1-Wasserstein distance, or the Kolmogorov distance.
\end{theorem}

\begin{theorem}[Functional Central Limit Theorem]
\label{FCLT}
Under the hypotheses of Theorem \ref{QCLT}, for any $R>0$,
the process $\{F_R(t)\}_{t\geq 0}$ has a $\gamma$-H\"older continuous modification (denoted also $F_R$), for any $\gamma \in (0,\frac{\beta}{2})$, where $\beta$ is given by \eqref{def-beta}.
Moreover,
\[
\frac{1}{R^{\beta/2}}F_R(\cdot) \stackrel{d}{\to} \mathcal{G}(\cdot) \quad \mbox{in $C[0,\infty)$ as $R \to \infty$},
\]
where $\{\mathcal{G}(t)\}_{t\geq 0}$ is a zero-mean Gaussian process with covariance 
$\mathbb{E}[\mathcal{G}(t) \mathcal{G}(s)]=K(t,s)$, and $K(t,s)$ given by Theorem \ref{cov-th}. Here $\stackrel{d}{\to}$ denotes the convergence in distribution, and $C[0,\infty)$ is equipped with the uniform convergence on compact sets.
\end{theorem}

The proofs of these theorems are based on a key estimate  which shows that the moments of the Malliavin derivative of the solution of \eqref{HAM} can be bounded, up to a constant, by a deterministic function (see relation \eqref{key-D} below). Similar estimates appear in all references dedicated to QCLT, where they play a crucial role. To prove this key estimate, we proceed as in \cite{BZ24}, developing a connection to (hAm) with delta initial velocity by using the form \eqref{def-G} of the fundamental solution $G$.

Theorem \ref{ergodic-th} follows from the key estimate \eqref{key-D} and a criterion which may be of independent interest (Lemma \ref{lem-key-Z} below). 
To prove Theorem \ref{cov-th} we show that the covariance of the solution of \eqref{HAM} coincides with the covariance of the solution of (hAm) driven by $\sqrt{m_2}W$, where $W$ is the Gaussian colored noise with covariance \eqref{def-cov-W}.

To prove Theorem \ref{QCLT}, we apply the recent result of Trauthwein \cite{trauthwein25}, which gives the optimal rates for the Wasserstein and Kolmogorov distances between $F/\sqrt{{\rm Var}(F)}$ and $Z \sim N(0,1)$, for a centered random variable $F$ with finite variance, which is Malliavin differentiable with respect to a compensated Poisson random measure. These estimates involve the first and second order Malliavin derivatives. Therefore, to  apply the result in \cite{trauthwein25}, we develop a similar key estimate for the second Malliavin derivative of the solution (see relation \eqref{key-D2} below). Different techniques are used for estimating the 7 quantities $\gamma_1,\ldots,\gamma_7$ which appear in the result of \cite{trauthwein25}, which rely on Young's inequality in the case when $k$ is integrable, respectively on Hardy-Littlewood-Sobolev inequality when $\kappa$ is the Riesz kernel. Finally, Theorem \ref{FCLT} follows by the classical method of finite dimensional convergence and tightness.

\begin{remark}
{\rm a) If $\kappa \in L^1(\mathbb{R})$, then $f=\kappa * \tilde{\kappa} \in L^1(\mathbb{R})$ by Young's inequality. In this case, the variance $\sigma_R^2(t)$ decays with rate $R$, as in the L\'evy white noise case and the Gaussian colored noise case with integrable kernel $f$ (see Theorem 1.2 of \cite{NZ22}). The decay rate $R^{-(1-\frac{1}{p})}$  in the QCLT (in the $d_{W}$, $d_{FM}$ or $d_K$ distances) is the same as in the L\'evy white noise case (see Theorem 1.1.(iii) of \cite{BZ24}), and depends on the parameter $p$ from \eqref{mp-m2p}. This can be explained since formally, the L\'evy white noise can be viewed as a L\'evy colored noise with integrable kernel $\kappa=\delta_0$. When $p=2$ (i.e. $m_4<\infty)$, this rate coincides with the rate $R^{-1/2}$ obtained in the case of the Gaussian colored noise case with integrable kernel $f$, for the QCLT in the total variation distance (see Theorem 1.2 of \cite{NZ22}).

\medskip

b) If $\kappa=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$, then $f =R_{1,\alpha}$. In this case, using the parametrization $\alpha=2H-1$ with $H \in (\frac{1}{2},1)$, we see that the decay rate $R^{2H}$ of $\sigma_R^2(t)$ is the same as in the Gaussian colored noise case (see  Proposition 3.3 of \cite{DNZ20}). In this Gaussian case, Theorem 1.1 {\em ibid.} gives the rate $R^{-(1-H)}=R^{-\frac{1-\alpha}{2}}$ for the QCLT in the total variation distance, which is almost the same as the rate $R^{-\varepsilon}$ with $\varepsilon \in (0,\frac{1-\alpha}{2})$ obtained in Theorem \ref{QCLT} above when $p=2$ (i.e. $m_4<\infty$).
}
\end{remark}

This article is organized as follows. In Section \ref{section-prelim}, we include some preliminaries about Poisson-Malliavin calculus and moment inequalities with respect to noises $L$ and $X$. In Sections \ref{section-Mall1} and \ref{section-Mall2}, we prove some key estimates for the first, respectively the second,  Malliavin derivative of the solution. In Section \ref{section-proofs}, we present the proofs of Theorems \ref{ergodic-th}, \ref{cov-th}, \ref{QCLT} and \ref{FCLT}. Appendix \ref{appA} contains some auxiliary results about Poisson-Malliavin calculus. Appendix \ref{appB} presents some inequalities for Riesz potentials.

\medskip

We conclude the introduction with few words about the notation. We write $a\lesssim b$ to indicate that $a \leq C b$ for some positive constant $C>0$ that does not depend on $(a,b)$. 
For any $p\geq 1$, we denote by $\|\cdot \|_p$ the norm in $L^p(\Omega)$.

theorem.content:
\label{thm:main_1}
    Let $u \in C^2(\mathbb{R}^n)$ be an even convex function such that its Hessian matrix $\nabla^2 u$ is positive definite, and let $\mu$ be the associated log-concave measure with density $\, \mathrm{d} \mu(x)=e^{-u(x)}\, \mathrm{d} x$. Given a convex and compact set $K \subset \mathbb{R}^n$ of class $C^2_+$, if \begin{equation}\label{eq:strong_dim_BM}
        \frac{\mu(K)}{\int_{\partial K} h_K(\nu_K) \, \mathrm{d} \mu} \leq p(\mu,K), 
    \end{equation}
    then \[ t \mapsto \mu(e^t K) \text{ is log-concave for }t \in \mathbb{R}. \]
    In particular, if $\mu$ satisfies \eqref{eq:strong_dim_BM} for every $K$ of class $C^2_+$, $\mu$ satisfies the \eqref{eq:B_conj}-conjecture as well.

ref_dict.thm:main_1:
\begin{theorem}\label{thm:main_1}
    Let $u \in C^2(\R^n)$ be an even convex function such that its Hessian matrix $\nabla^2 u$ is positive definite, and let $\mu$ be the associated log-concave measure with density $\di \mu(x)=e^{-u(x)}\di x$. Given a convex and compact set $K \subset \R^n$ of class $C^2_+$, if \begin{equation}\label{eq:strong_dim_BM}
        \frac{\mu(K)}{\int_{\partial K} h_K(\nu_K) \di \mu} \leq p(\mu,K), 
    \end{equation}
    then \[ t \mapsto \mu(e^t K) \text{ is log-concave for }t \in \R. \]
    In particular, if $\mu$ satisfies \eqref{eq:strong_dim_BM} for every $K$ of class $C^2_+$, $\mu$ satisfies the \eqref{eq:B_conj}-conjecture as well.
\end{theorem}

ref_dict.cor:strong_then_dim:
\begin{corollary}\label{cor:strong_then_dim}
    Consider a log-concave measure $\mu$ as in Theorem \ref{thm:main_1}. If $\mu$ satisfies \eqref{eq:strong_dim_BM} for every compact and convex set of class $C^2_+$, then \eqref{eq:dim_BM} holds true.
\end{corollary}

expanded_sketch:
The only explicit proof indication given after the main theorem is that “the strong dimensional Brunn--Minkowski condition implies the dimensional Brunn--Minkowski conjecture
\begin{equation}\label{eq:dim_BM}\tag{\rm dim-BM}
    \mu((1-t)K+tL)^{\frac{1}{n}}\geq (1-t)\mu(K)^{\frac{1}{n}}+t\mu(L)^{\frac{1}{n}}
\end{equation}
” and that this “follows immediately from an integration by parts, together with the symmetry of the problem” (see the following corollary.
\begin{corollary}\label{cor:strong_then_dim}
    Consider a log-concave measure $\mu$ as in Theorem \ref{thm:main_1}. If $\mu$ satisfies \eqref{eq:strong_dim_BM} for every compact and convex set of class $C^2_+$, then \eqref{eq:dim_BM} holds true.
\end{corollary}
). No proof sketch is provided there for the log-concavity conclusion of the main theorem itself.

expanded_theorem:
\label{thm:main_1}
    Let $u \in C^2(\mathbb{R}^n)$ be an even convex function such that its Hessian matrix $\nabla^2 u$ is positive definite, and let $\mu$ be the associated log-concave measure with density $\, \mathrm{d} \mu(x)=e^{-u(x)}\, \mathrm{d} x$. Given a convex and compact set $K \subset \mathbb{R}^n$ of class $C^2_+$, if 
\begin{equation}\label{eq:strong_dim_BM}
        \frac{\mu(K)}{\int_{\partial K} h_K(\nu_K) \di \mu} \leq p(\mu,K), 
    \end{equation}
    then \[ t \mapsto \mu(e^t K) \text{ is log-concave for }t \in \mathbb{R}. \]
    In particular, if $\mu$ satisfies the preceding inequality for every $K$ of class $C^2_+$, $\mu$ satisfies the following conjecture as well:
\begin{equation}\label{eq:B_conj} \tag{B}
    t \mapsto \mu(e^t K) \,, t \in \R, 
\end{equation}

ref_dict.prop3:
\begin{property}\normalfont\label{prop3}
			Let $\gcd(\theta,p)=1$. Assume that $\chi_p:\{\xi\in\mathbb{Z}:\gcd(\xi,p)=1\}\to\{-1,1\}$ is a function (e.g., the Legendre symbol) and suppose that
			$$\zeta_p(\theta)=\frac{1+\chi_p(\theta)}{2}.$$
			Thus, $\chi_p(\theta_1\theta_2)=\chi_p(\theta_1)\chi_p(\theta_2)$.
		\end{property}

ref_dict.prop2:
\begin{property}\normalfont\label{prop2}
			If $A_i=\{a:\zeta_p(a)=i,\ 1\leq a\leq p-1\}$ for $i=0,1$, then $|A_0|=|A_1|$. Hence, $|A_0|=|A_1|=\frac{p-1}{2}$.
		\end{property}

post_theorem_intro_text:
\begin{property}\normalfont\label{prop2}
			If $A_i=\{a:\zeta_p(a)=i,\ 1\leqslant a\leqslant p-1\}$ for $i=0,1$, then $|A_0|=|A_1|$. Hence, $|A_0|=|A_1|=\frac{p-1}{2}$.
		\end{property}

		\begin{property}\normalfont\label{prop3}
			Let $\gcd(\theta,p)=1$. Assume that $\chi_p:\{\xi\in\mathbb{Z}:\gcd(\xi,p)=1\}\to\{-1,1\}$ is a function (e.g., the Legendre symbol) and suppose that
			$$\zeta_p(\theta)=\frac{1+\chi_p(\theta)}{2}.$$
			Thus, $\chi_p(\theta_1\theta_2)=\chi_p(\theta_1)\chi_p(\theta_2)$.
		\end{property}

		\hspace{1cm} For Legendre cordial labeling and Legendre product cordial labeling, observe that if 
		\begin{equation}
			\zeta_p^1(a)=\frac{1+\chi_p(a)}{2}\label{eq0}
		\end{equation}
		where $\chi_p(a)=(a/p)$, then Properties~\ref{prop1}, \ref{prop2}, and \ref{prop3} hold for $\zeta_p^1$ (see Theorem 2.9 in \cite{Andoyo2} and Theorem 2.10 in \cite{Prudencio}). Additionally, for logarithmic cordial labeling, notice that if 
		\begin{equation}
			\ind_{\varpi_1,p}(a)\equiv \zeta_p^2(a)\pmod{2}\label{eq1}
		\end{equation}
		where $\varpi_1$ is a fixed primitive root of $p$, then $\zeta_p^2$ satisfies Properties~\ref{prop1} and \ref{prop2} (see Remarks 2 and 3 in \cite{Andoyo3} with $\eta=p$). Furthermore, let 
		\begin{equation}
			\zeta_p^3(a)=\frac{1+\chi_p(a)}{2}\label{eq2}
		\end{equation}
		with $\chi_p(a)=(-1)^{\ind_{\varpi_2,p}(a)}$, where $\varpi_2$ is a fixed primitive root of $p$. If $a_1\equiv a_2\pmod{p}$ with $\gcd(a_1,p)=\gcd(a_2,p)=1$, then by Remark 2 in \cite{Andoyo3}, we have $\ind_{\varpi_2,p}(a_1)=\ind_{\varpi_2,p}(a_2)$, which means $(-1)^{\ind_{\varpi_2,p}(a_1)}=(-1)^{\ind_{\varpi_2,p}(a_2)}$. Obviously, $\zeta_p^3(a_1)=\zeta_p^3(a_2)$, and so Property~\ref{prop1} holds. Now, assume that 
		$$A_i^2=\{a:\zeta_p^2(a)=i,\ 1\leqslant a\leqslant p-1\},\text{ and }$$
		$$A_i^3=\{a:\zeta_p^3(a)=i,\ 1\leqslant a\leqslant p-1\},$$
		for $i=0,1$ with $\varpi_1=\varpi_2$, where $\zeta_p^2$ is defined in (\ref{eq1}). If $a\in A_0^2$, then $\ind_{\varpi_2,p}(a)\equiv 0\pmod{2}$, and so $\chi_p(a)=1$. Hence, $a\in A_0^3$. Conversely, if $a\in A_0^3$, then 
		\begin{align*}
			1&=\frac{1+\chi_p(a)}{2}\tag{\text{by (\ref{eq2})}}\\
			2&=1+\chi_p(a)\\
			\chi_p(a)&=1\\
			(-1)^{\ind_{\varpi_2,p}(a)}&=1.
		\end{align*}
		Clearly, $\ind_{\varpi_2,p}(a)$ is even. Therefore, $a\in A_0^2$. Thus, $A_i^2=A_i^3$ for $i=0,1$, and it follows that $\zeta_p^3$ satisfies Property~\ref{prop2} since Property~\ref{prop2} holds for $\zeta_p^2$. Lastly, assume that $\gcd(a_1,p)=\gcd(a_2,p)=1$. Using Theorem 9.16 (ii) in \cite{Rosen} (page~369) with $m=p$ and $r=\varpi_2$, 
		$$\ind_{\varpi_2,p}(a_1a_2)\equiv \ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)\pmod{(p-1)}.$$
		Since $p-1$ is even, we have 
		$$\ind_{\varpi_2,p}(a_1a_2)\equiv \ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)\pmod{2},$$
		which means that $\ind_{\varpi_2,p}(a_1a_2)$ and $\ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)$ have the same parity. Consequently,
		\begin{align*}
			\chi_p(a_1a_2)&=(-1)^{\ind_{\varpi_2,p}(a_1a_2)}\\
			&=(-1)^{\ind_{\varpi_2,p}(a_1)+\ind_{\varpi_2,p}(a_2)}\\
			&=(-1)^{\ind_{\varpi_2,p}(a_1)}(-1)^{\ind_{\varpi_2,p}(a_2)}\\
			&=\chi_p(a_1)\chi_p(a_2).
		\end{align*}
		Hence, Property~\ref{prop3} holds. Additionally, the function 
		$$\zeta_p^4(a)=\frac{1-\chi(a)}{2},$$
		where $\chi_p(a)=(a/p)$, also satisfies Properties~\ref{prop1}, \ref{prop2}, and \ref{prop3} with the same explanation as $\zeta_p^1$ defined in (\ref{eq0}).

		\hspace{1cm} As we observed, several functions satisfy Properties~\ref{prop1}, \ref{prop2}, and/or \ref{prop3}. Motivated by this, this paper explores the arithmetic cordial labeling of some graphs. In Sections~\ref{sec3} and \ref{sec4}, we assume that $\eta=p$ is an odd prime.

ref_dict.hybrid large-sieve with level:
\begin{lemma}\label{hybrid large-sieve with level}
    Let $a_m$ be  any complex numbers  and $D>0$ be a fixed  integer and $T >0 $ be a real number. Let $f$ be a $C^1$ function on $[N,2N]$ such that $f^\prime$ does not vanish. Let  $X=\sup_{x \in [N,2N]} \frac{1}{|f^\prime(x)|}$. Then we have  
    \begin{align*}
   S_T(C,N;D):=\mathop{\sum_{\substack{c \sim C \\ (c,D)=1}}}\sumstar_{\gamma (cD)} \int_{-T}^{T} \Big|\sum_{N \leq m <  2N} a_m  e(tf(m)) e\left( \frac{\gamma m}{cD} \right) \Big| ^2\mathrm{d}t  \ll  (C^2DT+X) \sum_m|a_m|^2.
\end{align*}
\end{lemma}

