ref_dict.subsec:normalization:
\begin{proof}
  By Theorems~\ref{thm:subgroup_closed} and~\ref{thm:rep_in_K}, Remark~\ref{rem:rep-formula-tensor-K} and equation~\eqref{eq:scriptK_when_H_closed}, we have
  \begin{equation*}
    H^{q}_{\dd'}(\cinfty(G)) \cong H^{q}_{\dd'}(\K(G)) \cong \K(G) \otimes H^{q}_{\dd'}(\C_G) \cong \cinfty(G/H) \otimes H^{q}_{\dd'}(\C_G),
  \end{equation*}
  so the only thing left to prove is that $H^{q}_{\dd'}(\C_{G}) \cong H^q_{\mathrm{dR}} (H)$.

  Pick $\LL_1, \ldots, \LL_n, \MM_1, \ldots, \MM_m$ a basis of $\gr{g}$ such that $\gr{h} = \Span \{\LL_1, \ldots, \LL_n\}$, and $\tau_1, \ldots, \tau_n, \zeta_1, \ldots, \zeta_m \in \gr{g}^*$ the dual basis; we will regard them as global frames for $TG$ and $T^*G$, respectively. Let $\imath: H \hookrightarrow G$ be the inclusion map: denoting by $\LL_1^\bb, \ldots, \LL_n^\bb$ the vector fields induced on $H$, they form a global frame of $TH$, and $\LL_j^\bb$ is $\imath$-related to $\LL_j$ for each $j \in \{1, \ldots, n\}$. It follows that $\imath^* \zeta_k = 0$ for each $k \in \{1, \ldots, m\}$, since for each $p \in H$ we have
  \begin{equation*}
    \langle \imath^* \zeta_k|_p, \LL_j^\bb|_p \rangle
    =
    \langle \zeta_k|_{\imath(p)}, \imath_*(\LL_j^\bb|_p) \rangle
    =
    \langle \zeta_k|_{\imath(p)}, \LL_j|_{\imath(p)} \rangle
    =
    0,
    \quad \forall j \in \{1, \ldots, n\}.
  \end{equation*}
  A similar argument shows that $\imath^* \tau_1, \ldots, \imath^* \tau_n$ is a global frame for $T^*H$, dual to $\LL_1^\bb, \ldots, \LL_n^\bb$. Therefore, writing an arbitrary $u \in \cinfty(G; \LLambda^q)$ as~\eqref{eq:urepglobal}, we have
  \begin{equation*}
    \imath^* u = \psum_{|J| = q} (\imath^* u_J) \ \imath^* \tau_J.
  \end{equation*}
  Since $\imath^*: \cinfty(G) \to \cinfty(H)$ is surjective (because $H \sset G$ is a closed embedded submanifold), it follows that $\imath^*: \cinfty(G; \LLambda^q) \to \cinfty(H; \wedge^q \C T^* H)$ is also surjective,  with kernel
  \begin{equation*}
    \{ u \in \cinfty(G; \LLambda^q) \st u_J|_H = 0, \quad \forall J \}.
  \end{equation*}
  Moreover, since $\imath^* \zeta_k = 0$ for all $k \in \{1, \ldots, m\}$, it follows that $\imath^*(\dd u - \dd' u) = 0$, thus
  \begin{equation*}
    \imath^* (\dd' u) = \imath^* (\dd u) = \dd \imath^* u,
  \end{equation*}
  i.e.,~$\imath^*: \cinfty(G; \LLambda^q) \lra \cinfty(H; \wedge^q \C T^* H)$ is a chain map. In particular, it induces maps in cohomology
  \begin{equation*}
    \imath^*: H^q_{\dd'}(\cinfty(G)) \lra H^q_{\mathrm{dR}}(H).
  \end{equation*}

  By restriction, it is immediate that $\imath^*: \C_G(G; \LLambda^q) \lra \C_H(H; \wedge^q \C T^* H)$ is an isomorphism (where the target is the space $\Span_\C \{ \imath^* \tau_J \st |J| = q \}$ of left-invariant $q$-forms on $H$). Hence,
  \begin{equation*}
    \imath^*: H^q_{\dd'}(\C_{G}) \lra H^q_{\dd}(\C_H)
  \end{equation*}
  is also an isomorphism, where $H^q_{\dd}(\C_H)$ stands for left-invariant de Rham cohomology of $H$. Finally, $H^q_{\dd}(\C_H) \cong H^q_{\mathrm{dR}}(H)$ (by~\cite{ce48}, or our Theorem~\ref{thm:rep_in_K} plus Remark~\ref{rem:rep-formula-tensor-K} applied to the de Rham cohomology of $H$).
\end{proof}

\section{Tube structures and related equations}
\label{sec:tube}

In this final section, we address some questions raised in a previous paper~\cite{afjr24} in the context of tube structures.

Let $M$ be a smooth $n$-dimensional manifold, whose bundle of $q$-forms we denote by $\Lambda^q$; the pullback of the latter to $\Omega \dfn M \times \TT^m$ will be denoted, in this section, by $\LLambda^q$: the bundle of \emph{$(0,q)$-forms}. The choice of $m$ smooth, closed $1$-forms on $M$ -- call them $\omega_1, \ldots, \omega_m$ -- induced on $\Omega$ an involutive structure $\VV \sset \C T \Omega$, often called a \emph{tube structure} on $\Omega$. Its associated differential complex~\cite{bch_iis, treves_has} can be concretely written as
\begin{equation*}
  \dd' \dfn \dd_t + \sum_{k = 1}^m \omega_k \wedge \del_{x_k}:
  \cinfty(\Omega; \LLambda^q) \lra \cinfty(\Omega; \LLambda^{q + 1}),
  \quad q \in \{0, \ldots, n - 1 \},
\end{equation*}
with cohomology spaces (based on smooth sections) denoted by $H^q_{\dd'}(\cinfty(\Omega))$.

\subsection{Normalization}
\label{subsec:normalization}

Consider on $\Omega$ two tube structures $\VV, \VV^\bb \sset \C T \Omega$, associated to $1$-forms $\omega_1, \ldots, \omega_m$ and $\omega_1^\bb, \ldots, \omega_m^\bb$, respectively.
\begin{Thm}
  Suppose there exist $\psi_1, \ldots, \psi_m \in \cinfty(M; \R)$ such that
  \begin{equation*}
    \omega_k^\bb = \omega_k + \dd \psi_k,
    \quad k \in \{1, \ldots, m\}.
  \end{equation*}
  Then there exists a diffeomorphism $\Psi: \Omega \to \Omega$ such that
  \begin{equation}
    \label{eq:compatible}
    \Psi_*(\VV_p) = \VV^\bb_{\Psi(p)},
    \quad \forall p \in \Omega.
  \end{equation}
\end{Thm}
\begin{proof}
  We define $\Psi: M \times \TT^m \to M \times \TT^m$ by
  \begin{equation*}
    \Psi(t, x_1, \ldots, x_m) \dfn (t, x_1 + \psi_1(t), \ldots, x_m + \psi_m(t)),
  \end{equation*}
  where the sum $x_k + \psi_k(t)$ takes place in $\R / 2 \pi \Z$. This is clearly a diffeomorphism (its inverse has the same form). To prove~\eqref{eq:compatible}, we show instead the dual relationship between the annihilator bundles:
  \begin{equation*}
    \Psi^* (\T'^\bb_{\Psi(p)}) = \T'_p,
    \quad \forall p \in \Omega.
  \end{equation*}

  Let $p = (t,x) \in \Omega$, and pick a neighborhood of $\Psi(p) = (t, x^\bb)$ of the form $U^\bb \times V^\bb$, where:
  \begin{itemize}
  \item $U^\bb \sset M$ is a neighborhood of $t$ where one can find $\phi_1^\bb, \ldots, \phi_m^\bb \in \cinfty(U^\bb)$ local primitives for $\omega_1^\bb, \ldots, \omega_m^\bb$, respectively; and
  \item $V^\bb \sset \TT^m$ is a neighborhood of $x^\bb$ with standard coordinates $(x_1^\bb, \ldots, x_m^\bb)$.
  \end{itemize}
  Take now $U \times V \sset \Psi^{-1}(U^\bb \times V^\bb)$ a neighborhood of $p$, where $U \sset M$ is a neighborhood of $t$ and $V \sset \TT^m$ is a neighborhood of $x$ with standard coordinates $(x_1, \ldots, x_m)$. Using the definition of $\Psi$, one checks at once that $U \sset U^\bb$, hence $\phi_k \dfn \phi_k^\bb - \psi_k$ is a primitive for $\omega_k$ on $U$ for each $k \in \{1, \ldots, m\}$.

  This means that
  \begin{equation*}
    \zeta_k \dfn \dd x_k - \dd \phi_k,
    \quad k \in \{1, \ldots, m\},
  \end{equation*}
  span $\T'$ on $U \times V$, whereas
  \begin{equation*}
    \zeta_k^\bb \dfn \dd x_k^\bb - \dd \phi_k^\bb,
    \quad k \in \{1, \ldots, m\},
  \end{equation*}
  span $\T'^\bb$ on $U^\bb \times V^\bb$. We have, on $U \times V$:
  \begin{equation*}
    \Psi^* x_k^\bb = x_k^\bb \circ \Psi = x_k + \psi_k + 2\pi \nu_k,
    \quad
    \Psi^* \phi_k^\bb = \phi_k^\bb \circ \Psi = \phi_k^\bb
  \end{equation*}
  (recall that $\phi_k^\bb$ depends only on the $t$-variables), for some $\nu \in \Z^m$ fixed. Hence,
  \begin{equation*}
    \Psi^* \zeta_k^\bb
    = \dd \Psi^* x_k^\bb - \dd \Psi^* \phi_k^\bb
    = \dd (x_k + \psi_k + 2 \pi \nu_k) - \dd \phi_k^\bb
    = \zeta_k
  \end{equation*}
  for each $k \in \{1, \ldots, m\}$, thus proving our assertion.
\end{proof}

