    \quad \text{has closed range}
  \end{equation*}
  for all $1 \leq q \leq  n \dfn \rank (\VV)$. Moreover, in that case, we have
  \begin{equation}
    \label{eq:iso_scriptK}
    H^{q}_{\dd'} (\cinfty(G)) \cong \K(G) \otimes H^{q}_{\dd'} (\C_G),
    \quad 0 \leq q \leq n,
  \end{equation}
  topologically, where:
  \begin{itemize}
  \item $\K(G)$ is the space of homogeneous solutions of $\VV$: an $f \in \cinfty(G)$ belongs to $\K(G)$ if and only if $\LL f = 0$ whenever $\LL$ is a smooth section of $\VV$; and
  \item $H^{q}_{\dd'} (\C_G)$ is the space of left-invariant classes\footref{f1} in $H^{q}_{\dd'} (\cinfty(G))$.
