\beta \leq \frac{2\pi}{3}. 
\end{equation}
Then any solution ${u}$ of
\begin{equation} \label{Yao0105}
\begin{cases}
\Delta {u} + {f}({u}) = 0 & \text{in } \Sigma, \\
{u} > 0 & \text{in } \Sigma, \\
\frac{\partial {u}}{\partial \nu} = 0 & \text{on } \Gamma_{N}, \\
{u} = 0 & \text{on } \Gamma_{D}
\end{cases}
\end{equation}
satisfies the following properties: 
\begin{enumerate}[label = {\rm(\roman*)}, start = 1]
\item \label{Yaoit11a}
${u}$ is symmetric with respect to the line ${x}_{2} = 0$; 
\item \label{Yaoit11b}
${u}$ is monotone in ${x}_{2}$ in a half-domain, that is, ${x}_{2} {u}_{{x}_{2}} < 0$ for ${x} \in \Sigma$ with ${x}_{2} \neq 0$; 
\item \label{Yaoit11c}
${u}$ is monotone in ${x}_{1}$, that is, ${u}_{{x}_{1}} < 0$ in $\Sigma$. 
\end{enumerate}

