ref_dict.cor:CompPresAF:
\begin{corollary}\label{cor:CompPresAF}
Every c.e. presentation of a unital AF algebra is computable.
\end{corollary}

ref_dict.cor:NotCompCatAF:
\begin{corollary}\label{cor:NotCompCatAF}

\

\begin{enumerate}
    \item The AF algebra $C(\omega +1 )$ is not computably categorical.

    \item There is a unital dimension group that has two c.e. presentations that are 
    not computably isomorphic.

    \item There exist two computably presentable Bratteli diagrams that are
    equivalent but not computably equivalent.
\end{enumerate}
\end{corollary}

