ref_dict.l:zerobdy-cs:
\begin{lemma} \label{l:zerobdy-cs}
			Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ with jump measure $J(dx,dy)= J(x,y)\,m(dx)\,m(dy)$. 
	Let $\psi$ be the equilibrium potential for $K \subset \Omega$, where $\Omega$ is a non-polar, precompact open subset and $K$ is compact. Let $f \in \mathcal{F} \cap C(X)$ be   one of the following conditions hold:
	\begin{enumerate}[(a)]
		\item $f \equiv 0$ on some neighborhood of $\Omega^c$, or
		\item $f \equiv 0$ on some neighborhood of $K$.
	\end{enumerate}
	Then for any $U \subset X$, 
	\begin{equation} \label{e:zero-bdy}
	\int_{U} f^2\,d\Gamma(\psi,\psi) \le 48 \Gamma(f,f)(U).
	\end{equation}
\end{lemma}

ref_dict.t:char-hke:
\begin{theorem} \label{t:char-hke}
	Let $(X,d,m)$ be a metric measure space  that satisfies 	\hyperlink{vd}{$\on{VD}$} and \hyperlink{qrvd}{$\on{QRVD}$}. Let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form on $L^2(X,m)$. Then the following are equivalent:
	\begin{enumerate}[(a)]
		\item Jump kernel bound  \hyperlink{jphi}{$\on{J(\phi)}$}, and capacity upper bound \hyperlink{cap}{$\on{Cap(\phi)_{\le}}$}.
		\item Stable-like heat kernel bound \hyperlink{shk}{$\on{HK}(\phi)$}.
	\end{enumerate}
\end{theorem}

ref_dict.p:css:
\begin{prop} \label{p:css}
Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ that satisfies  \hyperlink{jphi}{$\operatorname{J(\phi)}$} and   \hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$}, where $\phi:[0,\infty) \to [0,\infty)$ is a scale function. Then there exists $C>0$ such that for any $r,\rho>0, f\in C(X) \cap \mathcal{F}$, the equilibrium potential $\psi$ for $\overline{B(x,r)} \subset B(x,2r)$ for the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
\begin{align} \label{e:css}
	\int_X f^2 \,d\Gamma^{(\rho)}(\psi,\psi) &= \int_{B(x,2r+\rho)} f^2 \,d\Gamma^{(\rho)}(\psi,\psi) \nonumber\\
	& \le C  	\int_{B(x,2r+2\rho)} \int_{B(x,2r+2\rho)} (f(y)-f(z))^2  J(y,z)\,m(dy)\,m(dz) \nonumber \\
	&\quad\quad\quad+ \frac{C}{\phi(r)} \int_{B(x,2r)} f^2\,dm 
\end{align}
\end{prop}

