  	&\le \int_{K \cup U} h(x)^2 \int_{B(x,\eta r/3)^c}  J(x,y) \,m(dy)\,m(dx)\nonumber \\
  	&\stackrel{\eqref{e:jump-tail}, \eqref{e:scale}}{\lesssim} \frac{1}{\phi(r)}\int_{K \cup U} h^2\,dm \stackrel{\eqref{e:wb0}}{\lesssim} \frac{1}{\phi(r)}\int_{B(x_0,(1+\eta)r)} f^2\,dm.
  \end{align}
  Combining \eqref{e:wb2},\eqref{e:wb3},\eqref{e:wb14},\eqref{e:wb19}, and \eqref{e:wb20}, we obtain 
  \begin{align*}
  \MoveEqLeft{\int_X \int_X  (h(x)-h(y))^2 J(x,y)  \,m(dy)\,m(dx)} \\ &\lesssim \int_{B(x_0,(1+\eta)r)} \int_{B(x_0,(1+\eta)r)}  (f(x)-f(y))^2 J(x,y)  \,m(dy)\,m(dx) + \frac{1}{\phi(r)}\int_{B(x_0,(1+\eta)r)} f^2\,dm.
  \end{align*}
  By Proposition \ref{p:domain} this implies that $h \in \mathcal{F}$ and that \eqref{e:wb} holds for the case $g=0$.

  It remains to show that $h \in C(X)$.  By the bounded overlap property \eqref{e:w-overlap}, \eqref{e:w-pu}, and the definition of $h$, it follows that the restriction of  $h$ on $\overline{B(x_0,r)}$ and on $\overline{B(x_0,r)}$ is continuous. Therefore it suffices to show that $h$ is continuous at each point of $\overline{B(x_0,r)} \setminus B(x_0,r)$.
  This follows from the fact that $\{\psi_{B_j}\}$ is a partition of unity satisfying \eqref{e:w-pu} and \cite[Proposition 3.2-(c)]{Mur24} using the same argument given in \cite[Proof of Lemma 5.9]{Mur24}. Indeed, by that argument, for any $\xi \in \overline{B(x_0,r)} \setminus B(x_0,r)$, there exists $s_0>0, K_0 >1$ such that for all $s \in (0,s_0)$, we have
  \[
  \sup_{y \in B(\xi,s)} \abs{h(y)-h(\xi)} \le   \sup_{y \in B(\xi,K_0 s)}  \abs{f(z)-f(\xi)}.
  \]
  By letting $s \downarrow 0$ and using the continuity of $f$, we obtain that $h$ is continuous.

\end{proof}

\subsection{Self-improvement of a simplified cutoff Sobolev inequality} \label{ss:self-improve}

We prove the following   version of cutoff Sobolev inequality using the Whitney blending result. This result can be viewed as a proof of the non-local analogue of simplified cutoff Sobolev inequality introduced in \cite[Definition 6.1]{Mur24} using the Whitney blending method of \cite{Eri}.

\begin{prop} \label{p:css}
Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ that satisfies  \hyperlink{jphi}{$\operatorname{J(\phi)}$} and   \hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$}, where $\phi:[0,\infty) \to [0,\infty)$ is a scale function. Then there exists $C>0$ such that for any $r,\rho>0, f\in C(X) \cap \mathcal{F}$, the equilibrium potential $\psi$ for $\overline{B(x,r)} \subset B(x,2r)$ for the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
\begin{align} \label{e:css}
	\int_X f^2 \,d\Gamma^{(\rho)}(\psi,\psi) &= \int_{B(x,2r+\rho)} f^2 \,d\Gamma^{(\rho)}(\psi,\psi) \nonumber\\
	& \le C  	\int_{B(x,2r+2\rho)} \int_{B(x,2r+2\rho)} (f(y)-f(z))^2  J(y,z)\,m(dy)\,m(dz) \nonumber \\
	&\quad\quad\quad+ \frac{C}{\phi(r)} \int_{B(x,2r)} f^2\,dm 
\end{align}

ref_dict.l:wb:
\begin{lem} \label{l:wb}
	For any $\eta \in (0,1)$, there exists $C$ depending only on the constants in \hyperlink{jphi}{$\on{J(\phi)}$},  \hyperlink{vd}{$\on{VD}$}, and   $\eta$  such that, for any $x_0 \in X, 0<r <\diam(X,d)/4$ and for any $f,g \in \mathcal{F} \cap C(X)$ and for any $A \in [2,\infty)$, there exists $h \in \mathcal{F} \cap C(X)$ such that  $h \equiv f$ on $B(x_0,r)$, $h \equiv g$ on $B(x_0,(1+\eta)r)^c$ and 
	\begin{align} \label{e:wb}
	\MoveEqLeft{\int_{B(x_0,Ar) \times B(x_0,Ar)}(h(x)-h(y))^2) \,J(dx,dy)} \\ &\le C \int_{B(x_0,Ar) \times B(x_0,Ar)}((f(x)-f(y))^2+(g(x)-g(y))^2) \,J(dx,dy)   		    + \frac{C}{\phi(r)} \int_{B(x_0,Ar)} (f-g)^2\,dm. \nonumber
	\end{align}
\end{lem}

