	\item \label{item:algo-correction-divisors}
	Using \cite[Lemma~2.7]{affchab1}, determine the vertical correction divisors $\Phi_{\fq}(G_i)$ for each prime $\fq$ of $K$. This involves the Moore--Penrose pseudoinverse of the intersection matrix of the mod-$\fq$ fibre computed in step~\ref{item:algo-intersection-numbers}.
	\item \label{item:algo-log-differentials}
	Find a basis $\omega_1,\ldots,\omega_{g+n-1}$ of the space of log differentials $\rH^0(X,\Omega^1(D))$ and compute their residues $\Res_Q(\omega_j) \in k(Q)$ at all cusps $Q \in |D|$.
	\item \label{item:algo-units}
	For each $Q\in |D|$, find $\varepsilon_i \in \cO_{k(Q)}^\times$ generating a full rank subgroup of $\cO_{k(Q)}^\times$.
	\item \label{item:algo-prime-ideal-generators}
	For finitely many ``special'' primes $\fq$ of $K$, determine generators $\rho_{\fq}$ of $\fq$ in $K^\times\otimes {\bQ}$.
	Similarly, for $Q\in |D|$ and finitely many ``special'' primes $\lambda$ of $k(Q)$, determine generators $\pi_{\lambda}$ of $\lambda$ in $k(Q)^\times\otimes {\bQ}$.
	\item \label{item:algo-integrals}
	Find a method for calculating $\fp$-adic integrals of log differentials on $X$.
	\item \label{item:algo-chabauty-function}
	For each $S$-integral reduction type~$\Sigma$, determine the matrix $M(\Sigma^{\csp})$ and find a non-trivial element $(a_1,\ldots,a_{g+n-1})$ in the kernel. Compute the constant $c=c(P_0,\Sigma,\omega)$ for the  Chabauty differential $\omega = \sum_j a_j \omega_j$.
	\item \label{item:algo-chabauty-locus}
	On each residue disc, expand the $\fp$-adic analytic function $P \mapsto \int_{P_0}^P \omega$ into a power series and determine the locus where $\int_{P_0}^P \omega=c$.
\end{enumerate}

