\label{thm:A}
	Let $\Sigma$ be an $S$-integral reduction type with cuspidal part $\Sigma^{\csp}$ and let $\mathfrak p \not\in S$ be a prime of $K$.
	If $(a_1,\ldots,a_{g+n-1}) \in K_{\mathfrak p}^{g+n-1}$ is contained in the kernel of the matrix $M(\Sigma^{\csp})$ defined in
\begin{equation}
	\label{eq:MSigma}
	M(U) \coloneqq \begin{pmatrix}
		A & B  \\
		0 & C  \\
		0 & D(U) 
	\end{pmatrix}
\end{equation}
--
\begin{equation}
		\label{eq:matrixD}
		D(U)_{i,j} \coloneqq \sum_{\substack{Q \in |D|,\\ \varphi\colon k(Q) \to \Kpbar}} \varphi(\Res_{Q} \omega_{g+j}) \sum_{\substack{\text{$\fq$ prime,}\\ \text{$\lambda|\fq$ in $\cO_{k(Q)}$}}} u_{i,\lambda} \log \varphi(\pi_{\lambda}).
	\end{equation}
let $\omega = \omega(\Sigma^{\csp}) \coloneqq a_1 \omega_1 + \dots + a_{g+n-1} \omega_{g+n-1}$ and let $c = c(P_0,\Sigma,\omega)$ be the constant defined by
\begin{equation}
	\label{eq:constants}
	c = c(b, \omega) \coloneqq \sum_{\substack{Q \in |D|,\\ \varphi\colon k(Q) \to \Kpbar}} \varphi(\Res_Q \omega) \sum_{\textnormal{$\lambda$ prime of $\cO_{k(Q)}$}} b_{\lambda} \log \varphi(\pi_{\lambda}).
	\end{equation}
and
\begin{equation}
\label{eq:b-lambda}
b_{\lambda} = -i_{\lambda}(\cP_0,\tilde\cQ) + i_{\lambda}(\Phi_{\fq}(\cpt(\Sigma_{\fq}) - \cpt_{\fq}(P_0)), \tilde\cQ),
\end{equation}
	Then
	\[
		\int_{P_0}^P \omega = c \quad \text{ for all } P \in \mathcal{Y}(\cO_{K,S})_\Sigma.
	\],

