ref_dict.cor:gor:
\begin{thm}\label{cor:gor}
    Let $(R,\fm,k)$ be an excellent Cohen--Macaulay local ring of the prime characteristic $p>0$. 
    \begin{enumerate}[label=(\alph*)]
        \item $R$ is tight Buchsbaum if and only if there exists a parameter ideal $\fq\subseteq R$ generated by parameter test elements such that $\fq:\fq^*\supseteq\fm$.\label{cor:gor-1}
        \item  The ring $R$ satisfies condition \ref{a} of \cref{thm:mainthm-restated} if and only if there exists a parameter ideal $$\mathfrak{Q}\subseteq \bigcap_{\fq} (\fq:\fq^F)=:J$$ (where the intersection is taken over all parameter ideals $\fq\subseteq R$) such that $\fm\subseteq \mathfrak{Q}:\mathfrak{Q}^F$. \label{cor:gor-2}
    \end{enumerate}

As Cohen--Macaulay rings are weakly $F$-nilpotent, \cref{cor:gor} shows all conditions of \cref{thm:mainthm} are equivalent in this setting.
\end{thm}

ref_dict.rmk: f-inj + buchs = f-buchs:
\begin{rmk}\label{rmk: f-inj  + buchs = f-buchs}
    Every excellent, $F$-injective generalized Cohen--Macaulay local ring $(R,\fm)$ is $F$-Buchsbaum. Indeed, from \cite[Theorem 1.1]{Ma15}, we know that $\fq=\fq^F$ for all parameter ideals $\fq$ from which we see that $\qs = \fq^{\lim}$. Further from \cite[Theorem~1.2]{Ma15}, it follows that $R$ is Buchsbaum. By \Cref{intro:thm-buchsbaum}, we have that the quantity \[
    e(\mfq)-\ell_R\left(R/\qs\right) = e(\mfq)-\ell_R\left(R/\mfq^{\lim}\right) = e(\mfq)-\ell_R\left(R/\mfq\right)+\ell_R\left(\mfq^{\lim}/\mfq\right)
    \] is a constant independent of $\mfq$.
\end{rmk}

ref_dict.thm:mainthm-B:
\begin{Theoremx}[\Cref{thm: CMFI-pun}]\label{thm:mainthm-B}
    Let $(R,\fm)$ be a $d$-dimensional excellent equidimensional local ring of prime characteristic $p>0$. The following are equivalent.
    \begin{enumerate}[label=(\alph*)]
        \item For all $\fp\in\Spec(R)\smallsetminus\{\fm\}$, the localization $R_\fp$ is Cohen--Macaulay and $F$-injective.
        \item $R$ is generalized Cohen--Macaulay and $\ell_R\left( 0^F_{H^d_\fm(R)}\right)<\infty$.
        \item $\sup\{\ell_R( \qs /\fq)\mid \fq \text{ is a parameter ideal}\}<\infty$.
    \end{enumerate}
\end{Theoremx}

ref_dict.prop:wfn-q-lim-F:
\begin{prp}\label{prop:wfn-q-lim-F}
  Let $(R, \fm)$ be a Buchsbaum, weakly $F$-nilpotent local ring of dimension $d>0$. For every parameter ideal $\fq\subseteq R$, we have $\fq^{\lim} \subseteq \fq^F$, and consequently, we have the equality $\qs = \mfq^F = (\mfq^{\lim})^F$.
\end{prp}

ref_dict.lem: qs/q constant length implies qF/q c:
\begin{thm}\label{lem: qs/q constant length implies qF/q constant length}
Let $(R,\fm,k)$ be an excellent, unmixed local ring of prime characteristic $p>0$, and of dimension $d>0$. If $R$ is $F$-Buchsbaum, then:
\begin{enumerate}[label=(\roman*)]
    \item $\qlf = \qs$ for each parameter ideal $\fq$ of $R$;
    \item $\ell_R(\mfq^F/\mfq)$ is a constant independent of parameter ideal $\mfq$;
    \item $e(\fq)-\ell_R(R/\fq^F)$ is a constant independent of  parameter ideal $\fq$.\label{thm:q-f-lim-3}
\end{enumerate}
\end{thm}

